import React from 'react';
import { View, Text, Stylesheet, Alert } from 'react-native';

//First navigate to GrusGorls folder in terminal using cd then navigate to Product folder using cd Product
//To run server use npm start in terminal
//To see what it looks like in app form, right click inspect and click on the app tab
// ctrl + c to stop server



function App() {
  return (
    <><div>
      <head><title>ThriftApp</title></head>
    </div><div>
        <h1>Welcome to ThriftApp</h1>
      </div>
      <div class="bottomNav">
        <a class="active" href="#home">Home</a>
        <a href="#reserved">Reserved</a>
        <a href="#map">Map</a>
        <a href="#account">Account</a>
      </div></>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 24,
    backgroundColor: '#eaeaea',
  },
  title: {
    marginTop: 16,
    paddingVertical: 8,
    borderWidth: 4,
    borderColor: '#20232a',
    borderRadius: 6,
    backgroundColor: '#61dafb',
    color: '#20232a',
    textAlign: 'center',
    fontSize: 30,
    fontWeight: 'bold',
  },
});

export default App;
